import {test} from 'node:test';import assert from 'node:assert/strict';import {ledger} from '../src/ledger.mjs';import {accept} from '../src/route.mjs';
test('single use through route preserves unrelated invitation',()=>{const b=ledger([{token:'a',team:'red',email:'x',expiresAt:10},{token:'b',team:'blue',email:'y',expiresAt:20}]);assert.equal(b.peek('a').email,'x');assert.deepEqual(accept(b,{token:'a'},()=>9),{status:'joined',team:'red'});assert.equal(b.peek('a'),undefined);assert.deepEqual(accept(b,{token:'a'},()=>9),{status:'missing'});assert.deepEqual(b.members(),[{team:'red',email:'x'}]);assert.equal(b.peek('b').email,'y');});
test('expiry boundary retains pending and does not join',()=>{const b=ledger([{token:'a',team:'r',email:'x',expiresAt:10}]);assert.deepEqual(accept(b,{token:'a'},()=>10),{status:'expired'});assert.equal(b.peek('a').token,'a');assert.deepEqual(b.members(),[]);});
test('past expiration and route clock contract',()=>{const b=ledger([{token:'a',team:'r',email:'x',expiresAt:10}]);let calls=0;assert.deepEqual(accept(b,{token:'a'},()=>{calls++;return 11;}),{status:'expired'});assert.equal(calls,1);assert.equal(b.peek('a').token,'a');assert.deepEqual(b.members(),[]);});
test('valid route uses one observation of time',()=>{const b=ledger([{token:'t',team:'r',email:'e',expiresAt:20}]);let calls=0;assert.deepEqual(accept(b,{token:'t'},()=>++calls===1?19:100),{status:'joined',team:'r'});assert.equal(calls,1);});
